}

input.newString:
  /**
   * Public API: execute a single named tool directly.
   */
  async executeTool(
    tool: string,
    args: ToolArgs,
    ctx: { workspaceId: string; contactId?: string; phone?: string },
  ): Promise<unknown> {
    const toolDeps = {
      actions: this.actions,
      riskGate: this.riskGate ?? undefined,
      prisma: this.prisma,
      auditService: this.auditService,
      logger: this.logger,
      openai: this.openai,
      primaryBrainModel: this.primaryBrainModel,
      fallbackBrainModel: this.fallbackBrainModel,
      agentRuntime: this.agentRuntime ?? undefined,
    };
    return executeToolAction(
      toolDeps,
      ctx.workspaceId,
      ctx.contactId || '',
      ctx.phone || '',
      tool,
      args,
    );
  }

  /** Build quoted reply plan (delegates to response service). */
  async buildQuotedReplyPlan(params: {
    workspaceId: string;
    contactId?: string;
    phone: string;
    draftReply: string;
    customerMessages: Array<{ content: string; quotedMessageId: string }>;
  }): Promise<Array<{ quotedMessageId: string; text: string }>> {
    return this.response.buildQuotedReplyPlan(
      this.openai,
      this.writerModel,
      this.fallbackWriterModel,
      this.planLimits,
      params,
    );
  }
}

